import { EventType } from '@reticlehq/core';
import { observeSafely } from './types.js';
import { isSyntheticInput } from '../actions/synthetic/synthetic-input.js';
const DECLINED = { alert: undefined, confirm: false, prompt: null };
const KINDS = ['alert', 'confirm', 'prompt'];
export function installDialogs(emit) {
    const slots = window;
    const originals = new Map();
    const patched = new Map();
    for (const kind of KINDS) {
        const original = slots[kind];
        if ('function' !== typeof original)
            continue;
        originals.set(kind, original);
        const callOriginal = original.bind(window);
        const wrapper = (...args) => {
            if (!isSyntheticInput())
                return callOriginal(...args);
            const answered = DECLINED[kind];
            const message = args[0];
            observeSafely(() => {
                emit(EventType.DIALOG_OPENED, {
                    kind,
                    ...('string' === typeof message ? { message } : {}),
                    ...(answered === undefined ? {} : { answered }),
                });
            });
            return answered;
        };
        patched.set(kind, wrapper);
        slots[kind] = wrapper;
    }
    return () => {
        for (const [kind, original] of originals) {
            if (slots[kind] === patched.get(kind))
                slots[kind] = original;
        }
    };
}
